contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller != address(this));
        require(c.balances(caller) == 0);

        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 callerBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 callerBalAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(reverted == false && callerBalAfter == callerBalBefore && cBalAfter == cBalBefore);
    }

    receive() external payable {}
}

